import SwiftUI

/// A skin is a named visual identity for the app: a palette, a surface
/// treatment, a type design, and a decoration scene. It is *not* a light/dark
/// pair — every skin carries both appearances (and high-contrast variants) in
/// the asset catalog, so the system's colour scheme keeps working inside any skin.
///
/// ## Where a skin's colours live
///
/// In `Shared/Assets.xcassets`, under `skin/<id>/…`, generated by
/// `design-system/color/generate_colorsets.py` from `palette-skins.json`
/// exactly like the default tokens. Each skin builds one ``SkinPalette`` from
/// the Xcode-generated symbols for its namespace — never a string lookup, so
/// a missing colorset is a compile error, and `ColorContrastTests` gates every
/// skin against the same floors as the default.
///
/// The default skin reads the un-namespaced tokens (`surface/card`,
/// `text/secondary`, `AccentColor`) — the catalog the app shipped with, untouched.
///
/// ## What a skin never touches
///
/// Graphs. The timeline spine, sparklines and PK charts read `series.color`
/// and `Color.primary` with their own opacities and never see `Theme`, so a
/// skin cannot restyle them. Per-substance identity colours (L3) and the L2
/// encoding scales (routes, dose tiers, phases) are likewise not a skin's to
/// change — only their surrounding chrome is.
///
/// Lives in `Shared/` so the widget and Live Activity targets can resolve the
/// active skin's colours from the same catalog; the store that *chooses* the
/// skin (`SkinStore`) is app-only.
enum Skin: String, CaseIterable, Identifiable, Sendable {
    /// The app's own look: soft pink light, hot pink dark, Liquid Glass.
    case piru
    /// Graphite — neutral grays, nothing moving. For people who want none of it.
    case graphite
    /// Linen — warm paper and charcoal, quiet.
    case linen
    /// Slate — cool blue-gray, quiet.
    case slate
    /// ely.pink — the author's homepage. Night (plum-black, hot pink, lilac,
    /// mint) and pink (cream cards on a pink ground with near-black edges).
    /// Solid edged cards with hard offset shadows; nothing tilts.
    case elyPink
    /// Tsuki — the author's journaling app. Deep purple night, lavender
    /// hairlines, glows instead of shadows, a sleeping moon and drifting stars.
    case tsuki
    /// Starfield — Astrelia's steel-blue sky: edged cards, gold stars, a dense
    /// twinkling field.
    case astrelia
    /// Jellyfish — deep water. Bioluminescent cyan and violet, soft glowing
    /// cards, bubbles rising and jellyfish swimming up behind everything.
    case jellyfish
    /// Paper garden — Origami's washi and Kaze's raked sand: matte paper,
    /// washi red, stones and moss, sakura petals.
    case paperGarden
    /// Hotaru — the author's ambient-art app. Fireflies over a dark meadow,
    /// an aurora at the top.
    case hotaru
    /// Yuki — the author's Pomodoro. Periwinkle, snow and frost, dual.
    case yuki
    /// Hebi arcade — the snake game's Neon City: magenta and cyan phosphor,
    /// a perspective grid, a pixel face.
    case hebi
    /// Kumo — the author's weather app. A sky that follows the real time of
    /// day and the season, frosted cards that let it through.
    case kumo
    /// dose.wiki — the partner encyclopedia's plum and fuchsia, their dose-tier
    /// ramp as the semantic colours, their molecule ring behind everything.
    case doseWiki

    var id: String { rawValue }

    /// Picker name. Localized like every user-facing string.
    var displayName: LocalizedStringResource {
        switch self {
        case .piru: "Piru"
        case .graphite: "Graphite"
        case .linen: "Linen"
        case .slate: "Slate"
        case .elyPink: "ely.pink"
        case .tsuki: "Tsuki"
        case .astrelia: "Starfield"
        case .jellyfish: "Jellyfish"
        case .paperGarden: "Paper Garden"
        case .hotaru: "Hotaru"
        case .yuki: "Yuki"
        case .hebi: "Hebi Arcade"
        case .kumo: "Kumo"
        case .doseWiki: "dose.wiki"
        }
    }

    /// One line under the name in the picker.
    var tagline: LocalizedStringResource {
        switch self {
        case .piru: "Soft pink, hot pink, liquid glass"
        case .graphite: "Neutral grays, nothing moving"
        case .linen: "Warm paper and charcoal, quiet"
        case .slate: "Cool blue-gray, quiet"
        case .elyPink: "Night and pink, stickers and pixels"
        case .tsuki: "Deep purple night, a sleeping moon"
        case .astrelia: "Steel blue and gold under a thousand stars"
        case .jellyfish: "Deep water, bioluminescence, jellyfish"
        case .paperGarden: "Washi, raked sand, sakura"
        case .hotaru: "Fireflies and an aurora"
        case .yuki: "Periwinkle, snow and frost"
        case .hebi: "Neon City on a CRT"
        case .kumo: "A sky that follows the day"
        case .doseWiki: "Plum and fuchsia, from the open encyclopedia"
        }
    }

    // MARK: - Current

    /// The skin the app is showing, readable from `Shared/` code that cannot
    /// see `SkinStore`. The app installs a provider that reads the observable
    /// store (so reads inside a `body` are tracked); before that, and in the
    /// extensions, it falls back to the persisted choice.
    nonisolated static var current: Skin { currentProvider() }

    /// Replaced once by `SkinStore.activate()` at launch; read on the main
    /// thread from view bodies. `nonisolated(unsafe)` because the members of
    /// this `Sendable` enum are nonisolated and the write happens before any
    /// view exists.
    nonisolated(unsafe) static var currentProvider: @Sendable () -> Skin = { SkinDefaults.storedSkin() }

    // MARK: - Palette

    /// The skin's tokens, from its catalog namespace.
    var palette: SkinPalette {
        switch self {
        case .piru: .piru
        case .graphite: .graphite
        case .linen: .linen
        case .slate: .slate
        case .elyPink: .elyPink
        case .tsuki: .tsuki
        case .astrelia: .astrelia
        case .jellyfish: .jellyfish
        case .paperGarden: .paperGarden
        case .hotaru: .hotaru
        case .yuki: .yuki
        case .hebi: .hebi
        case .kumo: .kumo
        case .doseWiki: .doseWiki
        }
    }

    /// Label colour on an ``accentMark`` fill (buttons, tab stickers). Gated
    /// 4.5:1 against ``accent``. The default skin's white-on-accent is the
    /// system's own choice for `.glassProminent`.
    var onAccent: Color { palette.onAccent }

    /// Brand accent and control tint. **Text-safe** in every skin: the app uses
    /// one token for both copy and marks, so where a skin's vivid mark colour
    /// fails as small text (ely.pink's hot pink on cream, 2.9:1) this is the
    /// darker `accent/text` twin and ``accentMark`` carries the vivid one.
    var accent: Color { palette.accent }

    /// The vivid accent for standalone marks: rings, glows, selection fills
    /// under white text. Gated at the 3:1 non-text floor, never used as copy.
    var accentMark: Color { palette.accentMark }

    /// De-emphasized body text. Gated AA 4.5:1 on `cardBackground`.
    var secondaryLabel: Color { palette.secondaryLabel }

    /// Page backdrop.
    var background: Color { palette.background }

    /// Card / raised surface fill.
    var cardBackground: Color { palette.cardBackground }

    /// Text-field and other input fills.
    var inputBackground: Color { palette.inputBackground }

    /// Eyebrows, section labels, sticker shadows — the skin's "wine". The
    /// default skin has no such role and uses secondary text.
    var eyebrow: Color { palette.eyebrow }

    /// Status colours. Skins may re-seed the L1 ladder; the roles and the
    /// `text` / `accent` split are fixed by the design system.
    func semantic(_ role: SemanticRole, _ variant: SemanticVariant) -> Color {
        palette.semantic(role, variant)
    }

    // MARK: - Decorations

    /// The decoration layer behind every screen. `nil` for skins that keep
    /// the ground plain. Colours come from the skin's own tokens; the app
    /// draws them, so nothing here is content.
    var decorations: SkinDecorations? {
        switch self {
        case .piru, .graphite, .linen, .slate:
            nil
        case .elyPink:
            SkinDecorations(
                scene: .stickers,
                glyphs: [
                    SkinGlyph("★", semantic(.caution, .accent)), SkinGlyph("☆", semantic(.caution, .accent)),
                    SkinGlyph("✦", .white), SkinGlyph("✧", .white),
                    SkinGlyph("♡", accentMark), SkinGlyph("♥", accentMark), SkinGlyph("✿", accentMark),
                    SkinGlyph("✚", eyebrow), SkinGlyph("♠", eyebrow), SkinGlyph("✗", eyebrow),
                    SkinGlyph("✦", semantic(.success, .accent)),
                ],
                // The site's `.term::before/::after`: ✧ on the top-right edge, ♡
                // on the bottom-left.
                frameCorners: (SkinGlyph("✧", semantic(.caution, .accent)), SkinGlyph("♡", accentMark)),
                // The site's cursor trail: a ♡ that floats up from every tap.
                tapGlyph: SkinGlyph("♡", accentMark),
            )
        case .tsuki:
            // Tsuki's `DreamyEffects`: a sparse field of haloed stars over two
            // nebula glows, and its sleeping moon.
            SkinDecorations(
                scene: .nightSky(SkinNightSky(
                    starColor: .Skin.Tsuki.Star.core,
                    haloColor: .Skin.Tsuki.Star.halo,
                    density: 0.55,
                    seed: 0x7511,
                    moon: true,
                    moonImage: .Skin.Tsuki.moon,
                    moonInk: palette.titleStroke,
                    moonBlush: semantic(.danger, .accent),
                    glows: [
                        SkinGlow(palette.shadow, at: UnitPoint(x: 0.7, y: 0.3), opacity: 0.22),
                        SkinGlow(semantic(.info, .accent), at: UnitPoint(x: 0.15, y: 0.85), opacity: 0.12),
                    ],
                )),
                glyphs: [
                    SkinGlyph("☾", .Skin.Tsuki.Star.core), SkinGlyph("✦", eyebrow), SkinGlyph("✧", eyebrow),
                    SkinGlyph("⋆", .Skin.Tsuki.Star.core), SkinGlyph("✩", accentMark),
                ],
                frameCorners: (SkinGlyph("☾", .Skin.Tsuki.Star.core), SkinGlyph("✦", eyebrow)),
                tapGlyph: SkinGlyph("✦", .Skin.Tsuki.Star.core),
            )
        case .astrelia:
            // Astrelia's `.starsky`: a dense white/blue field, gold stars.
            SkinDecorations(
                scene: .nightSky(SkinNightSky(
                    starColor: .Skin.Astrelia.Star.core,
                    haloColor: .Skin.Astrelia.Star.halo,
                    density: 1.0,
                    seed: 0xA57A,
                    milkyWay: true,
                    moon: false,
                    glows: [
                        SkinGlow(accentMark, at: UnitPoint(x: 0.5, y: -0.06), opacity: 0.16),
                        SkinGlow(eyebrow, at: UnitPoint(x: 0.1, y: 1.0), opacity: 0.11),
                        SkinGlow(accentMark, at: UnitPoint(x: 0.95, y: 1.0), opacity: 0.09),
                    ],
                )),
                glyphs: [
                    SkinGlyph("✦", semantic(.caution, .accent)), SkinGlyph("★", semantic(.caution, .accent)),
                    SkinGlyph("✧", .Skin.Astrelia.Star.core), SkinGlyph("⋆", .Skin.Astrelia.Star.core),
                    SkinGlyph("☾", semantic(.caution, .accent)), SkinGlyph("✦", accentMark),
                ],
                frameCorners: (SkinGlyph("✧", semantic(.caution, .accent)), SkinGlyph("⋆", .Skin.Astrelia.Star.core)),
                tapGlyph: SkinGlyph("✦", semantic(.caution, .accent)),
            )
        case .jellyfish:
            SkinDecorations(
                scene: .underwater(SkinUnderwater(
                    deep: .Skin.Jellyfish.Water.deep,
                    shallow: .Skin.Jellyfish.Water.shallow,
                    ray: .Skin.Jellyfish.Water.ray,
                    bubble: .Skin.Jellyfish.Water.bubble,
                    bells: [.Skin.Jellyfish.Jelly.violet, .Skin.Jellyfish.Jelly.cyan, .Skin.Jellyfish.Jelly.pink],
                )),
                glyphs: [],
                frameCorners: nil,
                // A bubble from every tap.
                tapGlyph: SkinGlyph("○", .Skin.Jellyfish.Water.bubble),
            )
        case .paperGarden:
            SkinDecorations(
                scene: .paper(SkinPaperGarden(
                    sand1: .Skin.Papergarden.Garden.sand1, sand2: .Skin.Papergarden.Garden.sand2,
                    groove: .Skin.Papergarden.Garden.groove, stone: .Skin.Papergarden.Garden.stone,
                    moss: .Skin.Papergarden.Garden.moss, petal: .Skin.Papergarden.Garden.petal,
                    firefly: .Skin.Papergarden.Garden.firefly, grain: palette.shadow,
                )),
                glyphs: [
                    SkinGlyph("✿", .Skin.Papergarden.Garden.petal), SkinGlyph("❀", .Skin.Papergarden.Garden.petal),
                    SkinGlyph("✾", semantic(.caution, .accent)), SkinGlyph("〜", palette.stroke),
                ],
                frameCorners: (SkinGlyph("✿", .Skin.Papergarden.Garden.petal), SkinGlyph("❀", semantic(.caution, .accent))),
                tapGlyph: SkinGlyph("✿", .Skin.Papergarden.Garden.petal),
            )
        case .hotaru:
            SkinDecorations(
                scene: .fireflies(SkinFireflies(
                    core: .Skin.Hotaru.Night.core, glow: .Skin.Hotaru.Night.glow,
                    fog: .Skin.Hotaru.Night.fog, tree: .Skin.Hotaru.Night.tree,
                    aurora: [.Skin.Hotaru.Night.aurora1, .Skin.Hotaru.Night.aurora2, .Skin.Hotaru.Night.aurora3, .Skin.Hotaru.Night.aurora4],
                )),
                glyphs: [SkinGlyph("✦", .Skin.Hotaru.Night.core), SkinGlyph("✧", .Skin.Hotaru.Night.glow), SkinGlyph("·", .Skin.Hotaru.Night.core)],
                frameCorners: nil,
                tapGlyph: SkinGlyph("✦", .Skin.Hotaru.Night.glow),
            )
        case .yuki:
            SkinDecorations(
                scene: .snow(SkinSnow(flake: .Skin.Yuki.Snow.flake, frost: .Skin.Yuki.Snow.frost)),
                glyphs: [SkinGlyph("❄", .Skin.Yuki.Snow.flake), SkinGlyph("✻", .Skin.Yuki.Snow.frost), SkinGlyph("❅", accentMark)],
                frameCorners: (SkinGlyph("❄", .Skin.Yuki.Snow.flake), SkinGlyph("✻", .Skin.Yuki.Snow.frost)),
                tapGlyph: SkinGlyph("❄", .Skin.Yuki.Snow.flake),
            )
        case .hebi:
            SkinDecorations(
                scene: .arcade(SkinArcade(
                    grid: .Skin.Hebi.Arcade.grid, wall: .Skin.Hebi.Arcade.wall, border: .Skin.Hebi.Arcade.border,
                    snake: .Skin.Hebi.Arcade.snake, snakeBody: .Skin.Hebi.Arcade.snakeBody,
                    food: .Skin.Hebi.Arcade.food, star: .Skin.Hebi.Arcade.star,
                )),
                glyphs: [
                    SkinGlyph("▪", accentMark), SkinGlyph("▴", .Skin.Hebi.Arcade.food),
                    SkinGlyph("●", semantic(.caution, .accent)), SkinGlyph("✦", accentMark),
                ],
                frameCorners: (SkinGlyph("✦", accentMark), SkinGlyph("▪", .Skin.Hebi.Arcade.food)),
                tapGlyph: SkinGlyph("▪", .Skin.Hebi.Arcade.food),
            )
        case .kumo:
            SkinDecorations(
                scene: .sky(SkinSky(
                    night: (.Skin.Kumo.Sky.night1, .Skin.Kumo.Sky.night2),
                    day: (.Skin.Kumo.Sky.day1, .Skin.Kumo.Sky.day2),
                    sunset: (.Skin.Kumo.Sky.sunset1, .Skin.Kumo.Sky.sunset2),
                    cloud: .Skin.Kumo.Sky.cloud, star: .Skin.Kumo.Sky.star, rain: .Skin.Kumo.Sky.rain,
                    sun: .Skin.Kumo.Sky.sun, moon: .Skin.Kumo.Sky.moon,
                    auroraPurple: semantic(.info, .accent), auroraCyan: accentMark,
                )),
                glyphs: [
                    SkinGlyph("☁", .Skin.Kumo.Sky.cloud), SkinGlyph("✦", semantic(.caution, .accent)),
                    SkinGlyph("☾", .Skin.Kumo.Sky.moon), SkinGlyph("✧", .Skin.Kumo.Sky.sun),
                ],
                frameCorners: (SkinGlyph("☁", .Skin.Kumo.Sky.cloud), SkinGlyph("✦", semantic(.caution, .accent))),
                tapGlyph: SkinGlyph("✦", semantic(.caution, .accent)),
            )
        case .doseWiki:
            // The site is quiet: its page halos, its molecule ring, no stickers.
            SkinDecorations(
                scene: .molecule(SkinMolecule(
                    image: .Skin.Dosewiki.molecule,
                    ink: .Skin.Dosewiki.Molecule.ink,
                    halos: [
                        SkinGlow(.Skin.Dosewiki.Halo.top, at: UnitPoint(x: 0.5, y: 0), opacity: 0.16),
                        SkinGlow(.Skin.Dosewiki.Halo.left, at: UnitPoint(x: 0, y: 0.5), opacity: 0.09),
                        SkinGlow(.Skin.Dosewiki.Halo.right, at: UnitPoint(x: 1, y: 0.6), opacity: 0.08),
                        SkinGlow(.Skin.Dosewiki.Halo.bottom, at: UnitPoint(x: 0.5, y: 1), opacity: 0.07),
                    ],
                )),
                glyphs: [],
                frameCorners: nil,
                tapGlyph: nil,
            )
        }
    }

    /// A dashed inner border inside every card — the site's `.frame::before`
    /// (`2px dashed var(--pink-hot)` inset 6px). `nil` for skins whose cards
    /// are plain surfaces.
    var cardInsetDash: Color? {
        switch self {
        case .elyPink: accentMark
        case .piru, .graphite, .linen, .slate, .tsuki, .astrelia, .jellyfish, .paperGarden, .hotaru, .yuki, .hebi, .kumo, .doseWiki: nil
        }
    }

    /// The corner of a small filled chip that is not drawn by ``SkinChrome``'s
    /// primitives (the white chips on the Library's gradient cards). `nil`
    /// keeps a capsule; an edged skin squares them like every other chip.
    var chipCornerRadius: CGFloat? {
        switch self {
        case .elyPink, .astrelia: 3
        case .paperGarden: 2
        case .hebi: 0
        case .piru, .graphite, .linen, .slate, .tsuki, .jellyfish, .hotaru, .yuki, .kumo, .doseWiki: nil
        }
    }

    /// The navigation large title's treatment. An edged skin fills it and
    /// gives it a hard drop like the site's `h1`; a soft skin gives it a glow.
    /// `nil` leaves the system's plain title.
    var titleOutline: SkinTitleOutline? {
        switch self {
        // dose.wiki's wordmark is flat; only `.wiki` takes the accent.
        case .piru, .graphite, .linen, .slate, .doseWiki: nil
        // The site's `h1`: hot pink at night, near-black in pink mode, with a
        // hard drop (wine at night, hot pink in pink mode).
        case .elyPink: SkinTitleOutline(
            fill: palette.titleFill, stroke: palette.titleStroke,
            shadow: palette.titleShadow, shadowOffset: CGSize(width: 3, height: 3), shadowBlur: 0,
        )
        case .astrelia: SkinTitleOutline(
            fill: palette.titleFill, stroke: palette.titleStroke,
            shadow: palette.titleShadow, shadowOffset: CGSize(width: 3, height: 3), shadowBlur: 0,
        )
        // Soft skins: no outline, the label colour, a coloured glow beneath.
        case .tsuki, .jellyfish, .hotaru, .yuki, .kumo: SkinTitleOutline(
            fill: nil, stroke: nil,
            shadow: palette.titleShadow, shadowOffset: .zero, shadowBlur: 14,
        )
        // Ink with a hard sakura drop, no outline: a stamp on paper.
        case .paperGarden: SkinTitleOutline(
            fill: palette.titleFill, stroke: nil,
            shadow: palette.titleShadow, shadowOffset: CGSize(width: 2, height: 2), shadowBlur: 0,
        )
        // A neon sign: cyan tube, magenta glow.
        case .hebi: SkinTitleOutline(
            fill: palette.titleFill, stroke: nil,
            shadow: palette.titleShadow, shadowOffset: .zero, shadowBlur: 10,
        )
        }
    }

    // MARK: - Surface treatment

    /// How cards and capsules are drawn. The default skin keeps the app's
    /// scheme-adaptive material; an edged skin draws a solid fill with a stroke
    /// and a hard offset shadow; a soft skin draws a solid fill with a hairline
    /// and a coloured glow — never a black shadow.
    var surface: SkinSurface {
        switch self {
        case .piru, .graphite: .glass
        case .linen: .paper(stroke: palette.stroke, grain: palette.shadow)
        case .slate: .soft(stroke: palette.stroke, glow: palette.shadow, glowRadius: 10)
        case .elyPink: .edged(
            stroke: palette.stroke, strokeWidth: 2.5,
            shadow: palette.shadow, shadowOffset: CGSize(width: 3, height: 3),
        )
        case .astrelia: .edged(
            stroke: palette.stroke, strokeWidth: 2.5,
            shadow: palette.shadow, shadowOffset: CGSize(width: 4, height: 5),
        )
        case .tsuki: .soft(stroke: palette.stroke, glow: palette.shadow, glowRadius: 14)
        case .jellyfish: .soft(stroke: palette.stroke, glow: palette.shadow, glowRadius: 18)
        case .hotaru: .soft(stroke: palette.stroke, glow: palette.shadow, glowRadius: 16)
        case .yuki: .soft(stroke: palette.stroke, glow: palette.shadow, glowRadius: 12)
        case .paperGarden: .paper(stroke: palette.stroke, grain: palette.shadow)
        case .hebi: .neon(stroke: palette.stroke, glow: palette.shadow)
        case .kumo: .frosted(stroke: palette.stroke, highlight: palette.shadow)
        // Their cards: a fuchsia hairline over a plum panel, a soft dark shadow.
        case .doseWiki: .soft(stroke: palette.stroke, glow: palette.shadow, glowRadius: 12)
        }
    }

    // MARK: - Type

    /// Applied once at the root. `nil` keeps the system default design; this
    /// reshapes every semantic text style in the app without touching call
    /// sites.
    ///
    /// **Must be `nil` for any skin with a custom face in ``typeface``.** A
    /// root `fontDesign` re-derives every SwiftUI font in the tree as a system
    /// font of that design — wrapped custom `UIFont`s included — so the display
    /// face would render only in UIKit's navigation bar and nowhere else.
    /// `SkinTypeTests` enforces the exclusion.
    var fontDesign: Font.Design? {
        switch self {
        case .piru, .graphite, .linen, .slate, .elyPink, .astrelia, .paperGarden, .hotaru, .hebi, .kumo, .doseWiki: nil
        // Tsuki is `.rounded` throughout; the jellyfish skin borrows it, and
        // Yuki's ultralight rounded timer is its whole identity.
        case .tsuki, .jellyfish, .yuki: .rounded
        }
    }

    /// Custom families by role. Body copy always stays the system face (with
    /// ``fontDesign``): the CJK body fonts a skin might want run 4–9 MB per
    /// weight, and the app ships in three scripts. Display and label faces
    /// are small and carry most of a skin's character.
    var typeface: SkinTypeface {
        switch self {
        case .piru, .graphite, .linen, .slate, .tsuki, .jellyfish, .yuki, .hotaru, .kumo: SkinTypeface(display: nil, label: nil)
        // Fredoka (variable, 159 KB) for titles; DotGothic16 (2 MB, includes
        // kana + JIS kanji) for chips and badges. Both SIL OFL, in Piru/Fonts.
        case .elyPink: SkinTypeface(display: "Fredoka", label: "DotGothic16")
        // Astrelia's site sets its titles in Fredoka too.
        case .astrelia: SkinTypeface(display: "Fredoka", label: nil)
        // Fraunces (variable), a soft serif for paper.
        case .paperGarden: SkinTypeface(display: "Fraunces", label: nil)
        // Press Start 2P is set wide; scaled down so a large title fits the bar.
        case .hebi: SkinTypeface(display: "Press Start 2P", label: "Press Start 2P", displayScale: 0.72)
        // Saira (variable, OFL): the squarish geometric sans closest to their
        // wordmark, which the site's font loader hides. Set a touch wide.
        case .doseWiki: SkinTypeface(display: "Saira", label: nil, displayScale: 0.94)
        }
    }
}

// MARK: - Palette

/// One skin's colour tokens. Every member is a catalog symbol (or, for the
/// default skin, the un-namespaced token the app shipped with).
struct SkinPalette: Sendable {
    let accent: Color
    let accentMark: Color
    let onAccent: Color
    let secondaryLabel: Color
    let background: Color
    let cardBackground: Color
    let inputBackground: Color
    let eyebrow: Color
    /// Card edge (edged skins) or hairline (soft skins).
    let stroke: Color
    /// Hard offset shadow (edged skins) or glow (soft skins).
    let shadow: Color
    /// Large-title fill, read against the *background*, not the card.
    let titleFill: Color
    let titleStroke: Color
    let titleShadow: Color
    let danger: (text: Color, accent: Color)
    let caution: (text: Color, accent: Color)
    let success: (text: Color, accent: Color)
    let info: (text: Color, accent: Color)

    func semantic(_ role: SemanticRole, _ variant: SemanticVariant) -> Color {
        let pair = switch role {
        case .danger: danger
        case .caution: caution
        case .success: success
        case .info: info
        }
