/// Font family names a skin bundles, by role. `nil` means the system face.
struct SkinTypeface: Equatable, Sendable {
    /// largeTitle · title · title2 · title3 · headline, and navigation titles.
    let display: String?
    /// Chips, badges — small categorical labels, never body copy or data.
    let label: String?
    /// Multiplies the display face's point size: a face set wide (a pixel
    /// face) needs less than the style's size to fit the same line.
    var displayScale: CGFloat = 1
}

/// The L1 status roles. A closed set — see `design-system/README.md`.
enum SemanticRole: CaseIterable, Sendable {
    case danger, caution, success, info
}

/// `text` is small copy (gated 4.5:1); `accent` is a standalone mark (3:1).
enum SemanticVariant: CaseIterable, Sendable {
    case text, accent
}

// MARK: - Decorations

/// A skin's decoration set: the scene `SkinBackdrop` draws behind every
/// screen, the glyph stickers it scatters over it, the pair that sits on a
/// glance card's corners, and the one that floats up from a tap.
struct SkinDecorations: Sendable {
    let scene: SkinScene
    /// Stickers scattered over the scene. Empty for none.
    let glyphs: [SkinGlyph]
    /// (top-right, bottom-left) on the large cards. `nil` for none.
    let frameCorners: (SkinGlyph, SkinGlyph)?
    /// Spawned at every tap by `TapTrail`. `nil` for none.
    let tapGlyph: SkinGlyph?
}

/// What `SkinBackdrop` paints under the stickers.
enum SkinScene: Sendable {
    /// ely.pink: a warm glow at the top and a faint dotted ground; the
    /// stickers carry the scene.
    case stickers
    /// A night sky: a twinkling, haloed starfield over nebula glows.
    case nightSky(SkinNightSky)
    /// Deep water: a depth gradient, light rays, rising bubbles, and
    /// jellyfish swimming up.
    case underwater(SkinUnderwater)
    /// Washi paper, raked sand around stones, sakura petals.
    case paper(SkinPaperGarden)
    /// A dark meadow: fireflies, fog, a tree line, an aurora.
    case fireflies(SkinFireflies)
    /// Falling snow and frost at the corners.
    case snow(SkinSnow)
    /// A perspective neon grid, pixel stars, a snake.
    case arcade(SkinArcade)
    /// A sky that follows the real time of day and season.
    case sky(SkinSky)
    /// dose.wiki: their page halos and their molecule ring, faint and slow.
    case molecule(SkinMolecule)
}

struct SkinMolecule: Sendable {
    /// The ring: their mark as a template image, resolved here on the main
    /// actor because the renderer is not.
    let image: ImageResource
    /// The ring is tinted with this.
    let ink: Color
    /// The site's page halos, top / left / right / bottom.
    let halos: [SkinGlow]
}

struct SkinPaperGarden: Sendable {
    let sand1: Color
    let sand2: Color
    let groove: Color
    let stone: Color
    let moss: Color
    let petal: Color
    let firefly: Color
    let grain: Color
}

struct SkinFireflies: Sendable {
    let core: Color
    let glow: Color
    let fog: Color
    let tree: Color
    /// Green, cyan, purple, pink — cycled along the ribbons.
    let aurora: [Color]
}

struct SkinSnow: Sendable {
    let flake: Color
    let frost: Color
}

struct SkinArcade: Sendable {
    let grid: Color
    let wall: Color
    let border: Color
    let snake: Color
    let snakeBody: Color
    let food: Color
    let star: Color
}

struct SkinSky: Sendable {
    let night: (Color, Color)
    let day: (Color, Color)
    let sunset: (Color, Color)
    let cloud: Color
    let star: Color
    let rain: Color
    let sun: Color
    let moon: Color
    let auroraPurple: Color
    let auroraCyan: Color
}

/// A radial glow on the ground: colour, centre, peak opacity.
nonisolated struct SkinGlow: Sendable {
    let color: Color
    let center: UnitPoint
    let opacity: Double

    init(_ color: Color, at center: UnitPoint, opacity: Double) {
        self.color = color
        self.center = center
        self.opacity = opacity
    }
}

struct SkinNightSky: Sendable {
    let starColor: Color
    let haloColor: Color
    /// 1.0 is Astrelia's dense field; Tsuki is sparser.
    let density: Double
    /// The star map's seed — two night skies must never share one.
    var seed: UInt64 = 0x57A2
    /// A denser diagonal band of faint stars, the Milky Way.
    var milkyWay = false
    /// A sleeping crescent moon.
    let moon: Bool
    /// The moon as drawn art — Tsuki's own icon, lifted with its glow — or
    /// `nil` to draw a crescent by hand.
    var moonImage: ImageResource? = nil
    /// The hand-drawn crescent's closed eyes and smile, and its blush.
    var moonInk: Color = .black
    var moonBlush: Color = .pink
    let glows: [SkinGlow]
}

struct SkinUnderwater: Sendable {
    /// The water column, bottom to top.
    let deep: Color
    let shallow: Color
    /// Light rays from the surface.
    let ray: Color
    let bubble: Color
    /// Bell colours the jellyfish cycle through.
    let bells: [Color]
}

/// One sticker glyph in a token colour.
struct SkinGlyph: Sendable {
    let symbol: String
    let color: Color

    init(_ symbol: String, _ color: Color) {
        self.symbol = symbol
        self.color = color
    }
}

/// A treated navigation title. Applied through UIKit's appearance proxy by
/// `SkinNavigationTitles` (large titles are drawn by the navigation bar, not
/// SwiftUI) and by `.skinHeroTitle()` on SwiftUI hero titles.
struct SkinTitleOutline: Sendable {
    /// `nil` keeps the label colour.
    let fill: Color?
    /// `nil` for no outline. Only the SwiftUI hero draws it — see
    /// `SkinNavigationTitles` for why the bar never strokes.
    let stroke: Color?
    let shadow: Color
    let shadowOffset: CGSize
    /// 0 for a hard drop; larger for a glow.
    let shadowBlur: CGFloat
}

/// The card treatment a skin asks for. See ``ThemedBackground``.
enum SkinSurface: Equatable, Sendable {
    /// `.ultraThinMaterial` in light, the skin's `cardBackground` in dark —
    /// the treatment the app shipped with.
    case glass
    /// Solid `cardBackground` in both schemes, a `strokeWidth` border in
    /// `stroke`, and a hard (unblurred) shadow of `shadow` offset by `shadowOffset`.
    case edged(stroke: Color, strokeWidth: CGFloat, shadow: Color, shadowOffset: CGSize)
    /// Solid `cardBackground`, a 1pt hairline in `stroke` at low opacity, and
    /// a coloured `glow` of `glowRadius` — never a black shadow.
    case soft(stroke: Color, glow: Color, glowRadius: CGFloat)
    /// Matte paper: solid fill, a 1pt ink `stroke` at low opacity, no shadow,
    /// and a `grain` tile over the fill.
    case paper(stroke: Color, grain: Color)
    /// Phosphor: a translucent dark fill, a 1.5pt `stroke` in the accent, an
    /// outer `glow` of the same colour, and an inner highlight line.
    case neon(stroke: Color, glow: Color)
    /// Frosted glass with no material: a translucent white fill, a white
    /// hairline `stroke`, and a `highlight` line along the top edge.
    case frosted(stroke: Color, highlight: Color)
}

/// The user's light/dark override. `system` defers to iOS.
enum SkinColorScheme: String, CaseIterable, Identifiable, Sendable {
    case system, light, dark

    var id: String { rawValue }

    /// Distinct from the dose-tier key `"Light"` (轻度), which is a different word.
    var displayName: LocalizedStringResource {
        switch self {
        case .system: "Follow System"
        case .light: "Light Mode"
        case .dark: "Dark Mode"
        }
    }

    /// What to hand `preferredColorScheme`. `nil` means follow the system.
    var colorScheme: ColorScheme? {
        switch self {
        case .system: nil
        case .light: .light
        case .dark: .dark
        }
    }
}

/// UserDefaults keys for the skin preference. One source of truth so the app's
/// `SkinStore` and the extensions read the same choice. Stored in the app group
/// suite so the widget and Live Activity can honour it.
nonisolated enum SkinDefaults {
    static let suite = "group.dev.yumeji.piru"
    static let skinKey = "skin"
    static let colorSchemeKey = "skinColorScheme"
    static let decorationsKey = "skinDecorations"
    static let skinDefault: Skin = .piru
    static let colorSchemeDefault: SkinColorScheme = .system
    static let decorationsDefault = true

    /// The persisted skin, for targets without a `SkinStore` (widgets). Falls
    /// back to the default when the stored value names a skin this build lacks.
    static func storedSkin(in defaults: UserDefaults? = UserDefaults(suiteName: suite)) -> Skin {
        guard let raw = defaults?.string(forKey: skinKey), let skin = Skin(rawValue: raw) else {
            return skinDefault
        }
        return skin
    }
}
